import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

function cli(file, ...args) {
  const r = spawnSync(process.execPath, ['./bin/subtrack.js', ...args, '--file', file], { encoding: 'utf8' });
  return r.stdout;
}

const dir = mkdtempSync(join(tmpdir(), 'subtrack-'));
const file = join(dir, 'subs.json');

try {
  console.log('Adding weekly subscription:');
  console.log(cli(file, 'add', 'Meal kit', '59.90', '--every', 'week', '--since', '2026-10-24'));

  console.log('Adding monthly subscription for comparison:');
  console.log(cli(file, 'add', 'Netflix', '12.99', '--every', 'month', '--since', '2026-09-27'));

  console.log('Listing subscriptions:');
  console.log(cli(file, 'list'));

  console.log('Monthly total:');
  console.log(cli(file, 'total'));

  console.log('Renewals in next 14 days:');
  console.log(cli(file, 'renewals', '--within', '14', '--today', '2026-10-24'));
} finally {
  rmSync(dir, { recursive: true, force: true });
}
"

