import('./src/dates.js').then(({ daysBetween, addDays }) => {
  const since = '1976-10-24';
  const today = '2026-10-24';

  const daysBetweenValue = daysBetween(since, today);
  console.log('Days between', since, 'and', today, ':', daysBetweenValue);
  console.log('Weeks:', (daysBetweenValue / 7).toFixed(4));
  console.log('Days % 7:', daysBetweenValue % 7);

  // Manually step through the loop
  let date = since;
  let iterations = 0;
  while (date < today && iterations < 3) {
    iterations++;
    const nextDate = addDays(date, 7);
    console.log('Iteration', iterations + ':', date, '→', nextDate);
    date = nextDate;
  }

  // Jump to near the end
  console.log('\\nJumping near the target date...');
  date = addDays(since, Math.floor(daysBetweenValue / 7) * 7);
  console.log('Date after', Math.floor(daysBetweenValue / 7), 'weeks:', date);
  console.log('Compare to today:', date, 'vs', today, '→', date < today ? 'needs more weeks' : 'passed today');

  if (date < today) {
    date = addDays(date, 7);
    console.log('After one more week:', date);
  }
});
"

