import('./src/cycles.js').then(({ monthlyCents, CYCLE }) => {
  // Verify the total calculation matches the documented behavior
  const subs = [
    { name: 'Meal kit', price: 5990, cycle: CYCLE.WEEK },
    { name: 'Netflix', price: 1299, cycle: CYCLE.MONTH }
  ];

  console.log('Individual monthly costs (rounded for display):');
  const displayedMonthly = [];
  for (const sub of subs) {
    const monthly = monthlyCents(sub);
    displayedMonthly.push(monthly);
    console.log('  ' + sub.name + ': €' + (monthly / 100).toFixed(2));
  }

  const displayedTotal = displayedMonthly.reduce((a, b) => a + b, 0);
  console.log('  Sum of displayed: €' + (displayedTotal / 100).toFixed(2));

  // Calculate total like the CLI does
  const SHARE_PER_MONTH = { [CYCLE.WEEK]: 52 / 12, [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 1 / 12 };
  const calculatedTotal = Math.floor(subs.reduce((sum, s) => sum + s.price * (SHARE_PER_MONTH[s.cycle] ?? 0), 0) + 1e-9);
  console.log('\\nActual total (unrounded values):');
  console.log('  Week: 5990 * (52/12) = ' + (5990 * 52 / 12).toFixed(2) + ' cents');
  console.log('  Month: 1299 * 1 = 1299 cents');
  console.log('  Sum: ' + (5990 * 52 / 12 + 1299).toFixed(2) + ' cents');
  console.log('  Floored: €' + (calculatedTotal / 100).toFixed(2));

  console.log('\\nDifference (cut-off cents):');
  console.log('  €' + ((displayedTotal - calculatedTotal) / 100).toFixed(2));
  console.log('\\n✓ This matches the requirement: \"rounded to the nearest cent like every');
  console.log('  monthly cost from now on (today they are cut off)\"');
});
"

