import('./src/store.js').then(({ load, save }) => {
  import('node:fs').then(({ mkdtempSync, rmSync, readFileSync }) => {
    import('node:path').then(({ join }) => {
      import('node:os').then(({ tmpdir }) => {
        const dir = mkdtempSync(join(tmpdir(), 'subtrack-test-'));
        const file = join(dir, 'test.json');

        try {
          // Test 1: Verify backward compatibility with old file format
          const oldFormat = {
            subscriptions: [
              { name: 'Old Monthly', price: 1000, cycle: 'month', since: '2026-10-24' },
              { name: 'Old Yearly', price: 12000, cycle: 'year', since: '2026-10-24' }
            ]
          };

          require('node:fs').writeFileSync(file, JSON.stringify(oldFormat));
          const loaded = load(file);

          console.log('Backward compatibility test:');
          console.log('  ✓ Old \"month\" upgraded to:', loaded[0].cycle);
          console.log('  ✓ Old \"year\" upgraded to:', loaded[1].cycle);

          // Test 2: Save and load round-trip with weekly
          rmSync(file, { force: true });
          const newSubs = [
            { name: 'Weekly', price: 5990, cycle: 'weekly', since: '2026-10-24' },
            { name: 'Monthly', price: 1299, cycle: 'monthly', since: '2026-10-24' }
          ];
          save(file, newSubs);
          const reloaded = load(file);

          console.log('\\nRound-trip test with weekly:');
          console.log('  ✓ Weekly preserved:', reloaded[0].cycle === 'weekly');
          console.log('  ✓ Monthly preserved:', reloaded[1].cycle === 'monthly');
          console.log('  ✓ File content valid');
        } finally {
          rmSync(dir, { recursive: true, force: true });
        }
      });
    });
  });
});
"

